INSERT INTO quality_profiles (name, description, upgrades_allowed, minimum_custom_format_score, upgrade_until_score, upgrade_score_increment) VALUES ('Ladder', 'One ladder for movies and TV: 2160p Remux (final) > 2160p WEB-DL > 1080p Remux > 1080p WEB-DL. 720p and SD are never grabbed automatically; grab them by hand from Interactive Search. WEB-DLs rank by vevv''s source gist for their own HDR type, then HDR type, then group. Remuxes need lossless audio and rank CiNEPHiLES > TRaSH tiers.', 1, -100000, -100000, 100);
